    other_ssmd = [human_isoform_ssmd[tissue].loc[human_isoform_ssmd[tissue].pid == isoform].ssmd.iloc[0] for tissue in other_tissues]

    if brain_ssmd < np.min(other_ssmd):
        return True

    else:
        return False
    

    
    

