def plot_cumulative(x, label, ax=None, zorder=1):
    x = sorted(x)
    y = np.arange(len(x))/len(x)
    if ax is None:
        plt.plot(x, y, linewidth=3, label=label)
    else:
        ax.plot(x, y, linewidth=3, label=label, zorder=zorder)

