def map_coordinates(df1, df2, length=200, min_span=1):
    """
    Map coordinates from two dataframes to a vector.
    
    df1, df2: dataframes with 'start' and 'end' columns, values between 0 and 1
    length: length of the output vector X
    min_span: minimum number of positions to mark for each row
    
    Returns: vector X of length `length`
    """
    X = np.zeros(length, dtype=int)
    
    # Helper to map fractional coordinates to integer indices
    def get_indices(start, end):
        # Convert to 0-based integer indices
        i_start = int(np.floor(start * length))
        i_end = int(np.ceil(end * length))
        
        # Ensure at least one position is selected
        if i_start == i_end:
            i_end = i_start + 1
        
        # Clip to vector length
        i_start = max(0, min(length-1, i_start))
        i_end = max(0, min(length, i_end))  # i_end is exclusive
        return range(i_start, i_end)
    
    # Process df1 (set to 2)
    for _, row in df1.iterrows():
        for idx in get_indices(row['start'], row['end']):
            X[idx] = 2
    
    # Process df2 (set to 1 only if currently 0)
    for _, row in df2.iterrows():
        for idx in get_indices(row['start'], row['end']):
            if X[idx] == 0:
                X[idx] = 1
    
    return X

