def get_coverage(bam, chrom, start, end, normalize=None):
    """
    Compute IGV-style coverage over a genomic interval.

    Parameters
    ----------
    bam : pysam.AlignmentFile
        Open BAM file
    chrom : str
        Reference name
    start : int
        0-based start (inclusive)
    end : int
        0-based end (exclusive)

    Returns
    -------
    np.ndarray
        Coverage array of length (end - start),
        including explicit zeros over introns (N) and deletions (D)
    """
    cov = np.zeros(end - start, dtype=np.int32)
    positions = np.arange(start, end)

    for read in bam.fetch(chrom, start, end):
        if read.is_unmapped:
            continue

        ref_pos = read.reference_start

        for op, length in read.cigartuples:
            # M, =, X → consume reference and add coverage
            if op in (0, 7, 8, 2):
                seg_start = max(ref_pos, start)
                seg_end   = min(ref_pos + length, end)
                if seg_start < seg_end:
                    cov[seg_start - start : seg_end - start] += 1
                ref_pos += length

            # N (intron) or D (deletion) → consume reference, zero coverage
            elif op in [3]:
                ref_pos += length

            # I, S, H, P → do not consume reference
            else:
                continue

    if normalize is not None:
        if normalize == 'max':
            cov = cov/np.max(cov)
        elif normalize == 'mean':
            cov = cov/np.mean(cov)

    return cov, positions

