    def plot_loadings(EL, metadata, gene, tissues, plot_title = ''):
        samples = EL.columns[6:]
        EL_annot = EL.loc[EL.gid == gene, samples].T
        EL_annot.columns = [f'isoform_{x}' for x in range(1, EL_annot.shape[1]+1)]

        sorted_samples = []
        for t in tissues:
            sorted_samples.extend(list(EL_annot.index.intersection(metadata.loc[metadata.Tissue == t].index)))
    
        
        annot = metadata.loc[sorted_samples]

        EL_annot = EL_annot.loc[sorted_samples]
        factor_barplot(EL_annot, annot, colores, tissues, 
                       ['#EEEE00', '#7A67EE', '#FF00FF'], sort_factor = True, plot_title = plot_title)

