    def remove_splicing_efficiency(human_EL, gene, annot):
        bed_cols = ['chrom', 'start', 'end']
        select_transcripts = list(annot.loc[(annot.gene == gene) & (~annot.efficiency_factor)].transcript.unique())

        EL_bed = human_EL.columns[:6]
        EL_samples = human_EL.columns[6:]

        if len(select_transcripts) >= 2:
            # for transcript in select_transcripts:
            
            remain_sum = human_EL.loc[human_EL.pid.isin(select_transcripts), EL_samples].sum(axis=0)
            if remain_sum.quantile(0.1) >= 0.25:
                corrected_EL = human_EL.loc[human_EL.pid.isin(select_transcripts), EL_samples].div(remain_sum, axis=1)

                new_EL = pd.concat([human_EL.loc[human_EL.pid.isin(select_transcripts), EL_bed], corrected_EL], axis=1)

                return new_EL
    
        return None


