def load_cassetteexonsdenovo_2():
    """Data for the CassetteExonsDeNovo panels, 42 cells replayed in run order."""
    data = {}
    # -- CassetteExonsDeNovo.ipynb cell 4 --
    gencode_exons_2 = pd.read_csv('../code/resources/annotation/Human/bed/exons.all.bed.gz', sep='\t')

    annot = pd.read_csv('../code/results/torino/Human/isoforms/corrected_annotated.isoforms.tab.gz', sep='\t')
    annot['gene'] = annot.transcript.apply(lambda x: x.split('.')[0])



    efficiency_factor = []
    for idx, row in annot.iterrows():
        appris_ref = row.appris_ref
        aver = appris_ref.split('/')
        if 'RI:' in appris_ref:
            ri_factor = [x for x in aver if x.startswith('RI:')][0]
            ri_numbers = int(ri_factor.split(':')[1])
            appris_length = int(row.appris_transcript_length)
        
            if ((ri_numbers <= 2) and (appris_length >= 5)) or ((ri_numbers <= 1) and (appris_length >= 3)):
                efficiency_factor.append(False)
            else:
                efficiency_factor.append(True)
        else:
            efficiency_factor.append(False)

    annot['efficiency_factor'] = efficiency_factor

    tested_genes_id = gencode_exons_2.loc[gencode_exons_2.gene_name.isin(annot.gene.unique())].gene_id.unique()
    # -- CassetteExonsDeNovo.ipynb cell 251 --
    good_isoforms = list(annot.loc[~annot.efficiency_factor].transcript)
    # -- CassetteExonsDeNovo.ipynb cell 129 --
    del casette_df_list
    del gencode_and_torino
    del torino_exon_intron_overlap
    del torino_constant_vastdb
    del torino_internal_exons_bed
    del gencode_cassette_exons_bed
    del cassette_bed
    del cassette_df
    del cassette_df_w_transcripts
    del cassette_overlaps
    del torino_introns_grouped
    del torino_introns_df
    del torino_internal_exons_df
    del torino_exons_grouped
    del torino_constant
    del torino_introns
    del gencode_casette_df
    del gencode_casette_df_list
    del gencode_cassette_exons_aver
    del gencode_cassette_exons2
    del gencode_exons_bed
    del gencode_exons_1
    del gencode_exons_2
    del gencode_exons_grouped
    del gencode_internal_exons_bed
