        with (ro.default_converter + pandas2ri.converter).context():
            pd_from_r_df = ro.conversion.get_conversion().rpy2py(df)

        #coords = list(pd_from_r_df['torino_K10']['coords'])[1:-1]#pd_from_r_df['torino_K10']['coords']

