    def get_gene_data(gene, annot, human_EL, tpm, human_metadata, gtex_colors2,
                      min_tpm=10, min_correct=0.9):
        """
        Build the X dataframe for a given gene with exp, load, and color columns.
        """
        IR_transcripts = annot.loc[(~annot.efficiency_factor) & (annot.appris_ref.apply(lambda x: 'RI:' in x))]
        eff_transcripts = annot.loc[annot.efficiency_factor]
        IR_transcripts_gp = IR_transcripts.groupby('gene')
        eff_transcripts_gp = eff_transcripts.groupby('gene')
        gtex_samples = human_EL.columns[6:]
        EL_gp = human_EL.groupby('gid')

        gene_EL = EL_gp.get_group(gene)
        IR_t = IR_transcripts_gp.get_group(gene).transcript.unique()

        try:
            eff_t = eff_transcripts_gp.get_group(gene).transcript.unique()
        except KeyError:
            eff_t = []

        transcripts = [x for x in gene_EL.index if x not in eff_t]


        tpm_row = tpm.loc[tpm.Description == gene, gtex_samples].iloc[0]

        norm_EL = gene_EL.loc[transcripts, gtex_samples] / gene_EL.loc[transcripts, gtex_samples].sum(axis=0)
        loadings = np.array(norm_EL.loc[IR_t, gtex_samples].sum(axis=0))

        X = human_metadata.loc[gtex_samples].copy()
        X['exp'] = np.log10(np.array(tpm_row.loc[gtex_samples]) + 1)
        X['load'] = loadings
        X['color'] = [gtex_colors2[t]['tissue_color_hex'] for t in X.Tissue]

        return X


    def plot_gene(gene, X, figsize=(4, 4), ci=0.9, exclude_from_reg=None):

        tail = (1 - ci) / 2
        pct_lo, pct_hi = tail * 100, (1 - tail) * 100
        t_crit = stats.t.ppf(1 - tail, df=len(X.Tissue.unique()) - 2)

        fig, ax = plt.subplots(figsize=figsize)

        for tissue, group in X.groupby('Tissue'):
            color = group['color'].iloc[0]
            med_x = group.exp.median()
            med_y = group.load.median()
            ci_x_lo, ci_x_hi = np.percentile(group.exp,  [pct_lo, pct_hi])
            ci_y_lo, ci_y_hi = np.percentile(group.load, [pct_lo, pct_hi])

            ax.scatter(med_x, med_y, c=color, zorder=3)
            ax.plot([ci_x_lo, ci_x_hi], [med_y, med_y], c=color, alpha=0.7)
            ax.plot([med_x, med_x], [ci_y_lo, ci_y_hi], c=color, alpha=0.7)

        # Linear regression on per-tissue medians
        medians = X.groupby('Tissue')[['exp', 'load']].median()
        if exclude_from_reg is not None:
            medians_reg = medians.drop(index=exclude_from_reg, errors='ignore')
        else:
            medians_reg = medians

        slope, intercept, r, p, _ = stats.linregress(medians_reg.exp, medians_reg.load)
        x_range = np.linspace(medians_reg.exp.min(), medians_reg.exp.max(), 100)
        y_pred = slope * x_range + intercept

        n = len(medians_reg)
        se = np.sqrt(
            np.sum((medians_reg.load - (slope * medians_reg.exp + intercept))**2) / (n - 2)
        ) * np.sqrt(
            1/n + (x_range - medians_reg.exp.mean())**2 / np.sum((medians_reg.exp - medians_reg.exp.mean())**2)
        )

        ax.plot(x_range, y_pred, color='black', linestyle='--', linewidth=1)
        ax.fill_between(x_range, y_pred - t_crit * se, y_pred + t_crit * se,
                        color='black', alpha=0.1)

        reg_label = f'r={r:.2f}, p={p:.2e}'
        if exclude_from_reg is not None:
            excl = [exclude_from_reg] if isinstance(exclude_from_reg, str) else exclude_from_reg
            reg_label += f'\n(excl. {", ".join(excl)})'
        ax.text(0.98, 0.98, reg_label,
                transform=ax.transAxes, ha='right', va='top', fontsize=9)

        handles = [
            mpatches.Patch(color=color, label=tissue)
            for tissue, color in X[['Tissue', 'color']].drop_duplicates().sort_values('Tissue').values
        ]
        ax.legend(handles=handles, title='Tissue', bbox_to_anchor=(1.05, 1), frameon=False, fontsize=7)

        # Auto-select tpm ticks based on data range
        candidates = [0, 1, 10, 100, 1000, 10000, 100000]
        x_min, x_max = X.exp.min(), X.exp.max()
        tpm_ticks = [t for t in candidates
                     if np.log10(t + 1) >= x_min and np.log10(t + 1) <= x_max]
        if len(tpm_ticks) < 2:
            tpm_ticks = candidates[
                max(0, bisect.bisect_left(candidates, int(10**x_min)) - 1):
                bisect.bisect_right(candidates, int(10**x_max)) + 1
            ]

        ticks = [np.log10(t + 1) for t in tpm_ticks]
        ax.set_xticks(ticks)
        ax.set_xticklabels([str(t) for t in tpm_ticks])
        ax.set_xlabel('TPM')
        ax.set_ylabel('IR loadings')
        ax.set_title(gene, fontstyle='italic')

        ax.spines[['top', 'right']].set_visible(False)

        # plt.show()
        return fig, ax

    
