def run_all(data_dir='figure_data', only=None, force=False):
    """Build the panel data, one source notebook at a time.

    Each loader's panels are pickled as soon as it finishes and its result is
    dropped before the next one starts, so a crash costs one loader rather than
    the whole run and memory does not accumulate across all six. A loader whose
    pickles are all present is skipped unless `force=True`.

        run_all()                      # everything still missing
        run_all(only=['UTR3.ipynb'])   # just that one
    """
    import gc
    import resource
    # Every path in the extracted cells is relative to analysis/, exactly as in
    # the source notebooks.
    data_dir = os.path.abspath(data_dir)
    os.chdir(ANALYSIS_DIR)
    os.makedirs(data_dir, exist_ok=True)
    data = {}
    for nbp, fn, panels in LOADERS:
        if only and nbp not in only:
            continue
        paths = {p: os.path.join(data_dir, p + '.pkl') for p in panels}
        if not force and all(os.path.exists(v) for v in paths.values()):
            for p, v in paths.items():
                with open(v, 'rb') as fh:
                    data[p] = pickle.load(fh)
            print(f'[skip] {nbp}: {len(panels)} panels already pickled', flush=True)
            continue
        print(f'[run ] {nbp} -> {len(panels)} panels', flush=True)
        produced = fn()
        for p, v in paths.items():
            with open(v, 'wb') as fh:
                pickle.dump(produced[p], fh)
        data.update(produced)
        del produced
        gc.collect()
        peak = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss / 1e6
        print(f'[done] {nbp}: pickled {len(panels)} panels, peak RSS {peak:.1f} GB',
              flush=True)
    print(f'[run_all] {len(data)} panels available in {data_dir}')
    return data


class LazyPanels(dict):
    """Panels on disk, unpickled on first use.

    The pickles total several GB (PCA_introns alone is 1.5 GB), so loading
    them all up front is what kills the kernel. Indexing works as with a plain
    dict -- data['panel_name'] -- but only the panels actually plotted are
    read, and release() drops one again once its figure is drawn.
    """

    def __init__(self, data_dir='figure_data'):
        super().__init__()
        self.data_dir = data_dir
        self.names = sorted(n[:-4] for n in os.listdir(data_dir)
                            if n.endswith('.pkl'))

    def __missing__(self, key):
        path = os.path.join(self.data_dir, key + '.pkl')
        if not os.path.exists(path):
            raise KeyError(f'{key}: not built yet, run run_all({self.data_dir!r})')
        with open(path, 'rb') as fh:
            self[key] = pickle.load(fh)
        return self[key]

    def __contains__(self, key):
        return key in self.names

    def keys(self):
        return list(self.names)

    def release(self, *keys):
        """Free the panels named, or every loaded panel when called bare."""
        import gc
        for k in (keys or list(super().keys())):
            super().pop(k, None)
        gc.collect()


def load_panels(data_dir='figure_data', lazy=True):
    """Panels from disk, without computing anything.

    lazy=True (the default) defers each unpickle to first use; pass
    lazy=False for the old behaviour of reading everything at once.
    """
    if lazy:
        return LazyPanels(data_dir)
    data = {}
    for name in sorted(os.listdir(data_dir)):
        if name.endswith('.pkl'):
            with open(os.path.join(data_dir, name), 'rb') as fh:
                data[name[:-4]] = pickle.load(fh)
    return data


